      BASS: { source: ["a clean 808 with a soft round attack","a sine sub that only moves on the chord change","a plucked synth bass, short and rubbery","a long 808 with a slow glide into each chord root","a fingered bass guitar sample, round and short","an 808 layered with a soft electric bass pluck"], tone: ["a clean round body with the top rolled off","soft saturation just for phone speakers","a tight decay that leaves a gap before each kick","glide only on the chord change","a slow low-pass opening on the hook","a short click on the attack, otherwise pure"], pattern: Base.BASS.pattern, human: Base.BASS.human },
      DRUMS: { kick: ["a soft round pop kick with a tight thud","a short kick with the sub cut so the bass carries","a dry knocking kick doubled a 16th before beat 3","a deep soft kick on 1 and the and of 2","a 3-3-2 kick pattern, bouncing","a tight clicky kick tucked under the sub"], snare: ["a soft layered snap and clap, wide and short","a side-stick click on 2 and 4","a snappy pitched-up clap with a short bright plate","a finger snap on the backbeat, dry and close","a clap stacked with a thin snare, a few milliseconds apart","a soft snare with its tail gated short"], hats: ["closed hats in light 8ths with a shaker on the 16ths","tight trap hats in 16ths, the same pattern every bar","a shaker loop with the accents drifting","soft closed hats, barely there in the verse","ticking hats with one open hat on the and of 4","bright hats pitched up and panned right"] },
